if(!defined('VELTRION_RUNTIME_GUARD') && file_exists(__DIR__ . '/../bootstrap/guard.php')){ @include_once __DIR__ . '/../bootstrap/guard.php'; }
  class FeatureAnalyzer { public function analyzeFile(string $filePath): array { if (!file_exists($filePath)) { throw new \InvalidArgumentException("Archivo de feature no encontrado: {$filePath}"); } $content = file_get_contents($filePath); return $this->analyzeContent($content, basename($filePath, '.md')); } public function analyzeContent(string $content, string $fallbackName = 'Custom Feature'): array { $title = $fallbackName; if (preg_match('/^#\s*Feature:\s*(.+)$/m', $content, $matches)) { $title = trim($matches[1]); } elseif (preg_match('/^#\s*(.+)$/m', $content, $matches)) { $title = trim($matches[1]); } $requirements = $this->extractSectionList($content, ['Requisitos', 'Requirements', 'Objetivo']); $fields = $this->extractSectionList($content, ['Campos', 'Fields']); $rules = $this->extractSectionList($content, ['Reglas', 'Rules', 'Business Rules']); $tests = $this->extractSectionList($content, ['Tests', 'Pruebas']); $ambiguities = []; if (empty($fields) && (str_contains(strtolower($content), 'crud') || str_contains(strtolower($content), 'módulo'))) { $ambiguities[] = [ 'type' => 'FIELDS_UNSPECIFIED', 'question' => 'Campos de la entidad no especificados explícitamente.', 'recommendation' => 'Se usarán campos por defecto (name, email, status).' ]; } if (str_contains(strtolower($content), 'eliminar') && !str_contains(strtolower($content), 'soft')) { $ambiguities[] = [ 'type' => 'DELETION_STRATEGY', 'question' => '¿La eliminación debe ser física (HARD_DELETE) o lógica (SOFT_DELETE)?', 'recommendation' => 'Estrategia predeterminada: Eliminación Física en repositorio.' ]; } return [ 'title' => $title, 'requirements' => $requirements, 'fields' => $fields, 'rules' => $rules, 'tests' => $tests, 'ambiguities' => $ambiguities, 'raw_content' => $content ]; } private function extractSectionList(string $content, array $sectionHeaders): array { $items = []; foreach ($sectionHeaders as $header) { $pattern = '/##\s*' . preg_quote($header, '/') . '\s*\n(.*?)(?=\n##|\z)/s'; if (preg_match($pattern, $content, $matches)) { $sectionText = trim($matches[1]); $lines = explode("\n", $sectionText); foreach ($lines as $line) { $line = trim($line); if (str_starts_with($line, '-') || str_starts_with($line, '*')) { $items[] = trim(ltrim($line, '-* ')); } elseif (!empty($line)) { $items[] = $line; } } break; } } return $items; } } 